        // floor \u51fd\u6570\u7528\u4e8e\u5411\u4e0b\u53d6\u6574\n        int bucketCount = (int) Math.floor((maxValue - minValue) / bucketSize) + 1;\n        // \u4f7f\u7528\u4e8c\u7ef4\u6570\u7ec4\uff0c\u5176\u5b9e\u4e5f\u53ef\u4ee5\u4f7f\u7528\u4e0b\u9762 ArrayList\uff0c\u5b83\u4f1a\u81ea\u52a8\u6269\u5bb9\n        // ArrayList<ArrayList<Integer>> bucketArr = new ArrayList<>(bucketNum);\n        int[][] buckets = new int[bucketCount][0];\n\n        // \u5229\u7528\u6620\u5c04\u51fd\u6570\u5c06\u6570\u636e\u5206\u914d\u5230\u5404\u4e2a\u6876\u4e2d\uff08\u5176\u5b9e\u6709\u70b9\u50cf HashMap \u7684\u5de5\u4f5c\u539f\u7406\uff0c\u4e0d\u8fc7\u5b83\u662f\u907f\u514d\u51b2\u7a81\uff0c\u800c\u8fd9\u91cc\u65e0\u9700\u907f\u514d\uff09\n        for (int i = 0; i < arr.length; i++) {\n            int index = (int) Math.floor((arr[i] - minValue) / bucketSize);\n            buckets[index] = arrAppend(buckets[index], arr[i]);\n        }\n\n        int arrIndex = 0;\n        for (int[] bucket : buckets) {\n            if (bucket.length <= 0) {\n                continue;\n            }\n\n            // \u5bf9\u6bcf\u4e2a\u6876\u8fdb\u884c\u6392\u5e8f\uff0c\u8fd9\u91cc\u4f7f\u7528\u4e86\u63d2\u5165\u6392\u5e8f\n            bucket = insertSort.sort(bucket);\n            for (int value : bucket) {\n                arr[arrIndex++] = value;\n            }\n        }\n\n        return arr;\n    }\n\n    /**\n     * \u81ea\u52a8\u6269\u5bb9\uff0c\u5e76\u4fdd\u5b58\u6570\u636e\n     *\n     * @param arr\n     * @param value\n     */\n    private int[] arrAppend(int[] arr, int value) {\n        // \u5bf9 arr \u8fdb\u884c\u62f7\u8d1d\uff0c\u4e0d\u6539\u53d8\u53c2\u6570\u5185\u5bb9\uff0c\u8fd9\u91cc\u662f\u6269\u5bb9\u4e00\u4f4d\n        arr = Arrays.copyOf(arr, arr.length + 1);\n        arr[arr.length - 1] = value;\n        return arr;\n    }\n\n}\n"})})]})}function d(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(u,{...e})}):u(e)}}}]